void main()=> runApp(MaterialApp(debugShowCheckedModeBanner:false, home: LoginScreen()));

class LoginScreen extends StatefulWidget{ @override State<LoginScreen> createState()=> _L(); }
class _L extends State<LoginScreen>{
  final c=TextEditingController(); String sp="1234";
  void initState(){ super.initState(); SharedPreferences.getInstance().then((p)=> setState(()=> sp=p.getString('app_password')??"1234")); }
  Widget build(BuildContext b){ return Scaffold(backgroundColor:Color(0xFF2E7D32),body:Center(child:Card(margin:EdgeInsets.all(24),child:Padding(padding:EdgeInsets.all(22),child:Column(mainAxisSize:MainAxisSize.min,children:[
    Icon(Icons.apartment,size:60,color:Color(0xFF2E7D32)),SizedBox(height:10),Text("Estate Management",style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),SizedBox(height:20),
    TextField(controller:c,obscureText:true,decoration:InputDecoration(labelText:"Password",border:OutlineInputBorder(),prefixIcon:Icon(Icons.lock))),SizedBox(height:15),
    SizedBox(width:double.infinity,height:45,child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Color(0xFF2E7D32)),onPressed:()async{var p=await SharedPreferences.getInstance();String r=p.getString('app_password')??"1234";if(c.text==r)Navigator.pushReplacement(b,MaterialPageRoute(builder:(_)=>Home()));else ScaffoldMessenger.of(b).showSnackBar(SnackBar(content:Text("Wrong! Default 1234")));},child:Text("LOGIN",style:TextStyle(color:Colors.white)))),SizedBox(height:8),Text("Default: 1234",style:TextStyle(fontSize:11,color:Colors.grey))
  ]))))); }
}

class Home extends StatefulWidget{ @override State<Home> createState()=> _H(); }
