  _save()async{var p=await SharedPreferences.getInstance(); await p.setString('estate_name',en); await p.setString('props',jsonEncode(props)); await p.setString('tens',jsonEncode(tens)); await p.setString('pays',jsonEncode(pays));}
  _editE(){var cc=TextEditingController(text:en); showDialog(context:context,builder:(_)=>AlertDialog(title:Text("Editable Estate Name"),content:TextField(controller:cc,decoration:InputDecoration(border:OutlineInputBorder(),labelText:"Estate Name")),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text("Cancel")),ElevatedButton(onPressed:(){setState(()=>en=cc.text); _save(); Navigator.pop(context);},child:Text("Save"))]));}
