    showDialog(context:context,builder:(_)=>AlertDialog(title:Text("Add Tenant - All Charges"),content:SingleChildScrollView(child:Column(children:[
      TextField(controller:n,decoration:InputDecoration(labelText:"Tenant Name",border:OutlineInputBorder())),SizedBox(height:8),
      TextField(controller:ph,decoration:InputDecoration(labelText:"Phone",border:OutlineInputBorder())),SizedBox(height:8),
      TextField(controller:pl,decoration:InputDecoration(labelText:"Plot No",border:OutlineInputBorder())),SizedBox(height:12),
      Text("PURCHASE, SECURITY, DEVELOPMENT, ESTATE DUE (₦)",style:TextStyle(fontWeight:FontWeight.bold,fontSize:11)),SizedBox(height:8),
