      TextField(controller:de,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:"Development",border:OutlineInputBorder())),SizedBox(height:8),
      TextField(controller:du,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:"Estate Due",border:OutlineInputBorder())),
    ])),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text("Cancel")),ElevatedButton(onPressed:(){double a=double.tryParse(pu.text)??0,b=double.tryParse(se.text)??0,c=double.tryParse(de.text)??0,d=double.tryParse(du.text)??0,tt=a+b+c+d; setState(()=>tens.add({"name":n.text,"phone":ph.text,"plot":pl.text,"pur":a,"sec":b,"dev":c,"due":d,"tot":tt,"paid":0.0,"bal":tt})); _save(); Navigator.pop(context);},child:Text("Save"))]));}
  _det(int idx){var t=tens[idx]; var pc=TextEditingController(); showModalBottomSheet(context:context,isScrollControlled:true,builder:(_)=>Padding(padding:EdgeInsets.fromLTRB(15,15,15,MediaQuery.of(context).viewInsets.bottom+15),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[
    Center(child:Container(width:40,height:4,color:Colors.grey)),SizedBox(height:12),Text(t['name'],style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text("Phone:${t['phone']} | Plot:${t['plot']}"),Divider(),
    Text("TENANTS MENU CHARGES",style:TextStyle(fontWeight:FontWeight.bold,color:Color(0xFF2E7D32))),Text("Purchase: ₦${t['pur']}\nSecurity: ₦${t['sec']}\nDevelopment: ₦${t['dev']}\nEstate Due: ₦${t['due']}"),SizedBox(height:8),
    Container(width:double.infinity,padding:EdgeInsets.all(12),decoration:BoxDecoration(color:Color(0xFFE8F5E9),borderRadius:BorderRadius.circular(8)),child:Text("TOTAL: ₦${t['tot']}\nPAID: ₦${t['paid']}\nBALANCE: ₦${t['bal']}",style:TextStyle(fontWeight:FontWeight.bold,color:Color(0xFF2E7D32)))),
