    SizedBox(height:12),Row(children:[Expanded(child:OutlinedButton.icon(icon:Icon(Icons.receipt),label:Text("Receipt"),onPressed:(){showDialog(context:context,builder:(_)=>AlertDialog(title:Text("$en\nRECEIPT"),content:Text("Tenant:${t['name']}\nPlot:${t['plot']}\nPhone:${t['phone']}\nDate:${DateTime.now().toString().substring(0,10)}\n\nPurchase:₦${t['pur']}\nSecurity:₦${t['sec']}\nDev:₦${t['dev']}\nEstate Due:₦${t['due']}\n-----\nTotal:₦${t['tot']}\nPaid:₦${t['paid']}\nBal:₦${t['bal']}\n\nThanks!\n$en"),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text("Close"))]));})),SizedBox(width:8),Expanded(child:OutlinedButton.icon(icon:Icon(Icons.notifications_active),label:Text("Alert"),onPressed:(){var mc=TextEditingController(text:"Hello ${t['name']}, this is $en. Your balance ₦${t['bal']} for Plot ${t['plot']}. Purchase ₦${t['pur']}, Sec ₦${t['sec']}, Dev ₦${t['dev']}, Due ₦${t['due']}. Please pay. Thanks."); showDialog(context:context,builder:(_)=>AlertDialog(title:Text("Instant Tenant Alert"),content:TextField(controller:mc,maxLines:5,decoration:InputDecoration(border:OutlineInputBorder())),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:Text("Cancel")),ElevatedButton(onPressed:(){Navigator.pop(context); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text("Alert ready for ${t['phone']}")) );},child:Text("Send"))]));}))])
