      SizedBox(height:20),Text("Quick Actions",style:TextStyle(fontWeight:FontWeight.bold,fontSize:16)),SizedBox(height:12),
      Row(children:[Expanded(child:qk(Icons.add_home_work,"Add\nProperty",_addP)),SizedBox(width:10),Expanded(child:qk(Icons.people,"Tenants",(){setState(()=>this.i=1);})),SizedBox(width:10),Expanded(child:qk(Icons.receipt_long,"Payments",(){setState(()=>this.i=1);} )) ] ),
      SizedBox(height:20),Text("Recent Tenants",style:TextStyle(fontWeight:FontWeight.bold)),
     ...tens.take(5).map((t)=>Card(child:ListTile(title:Text(t['name'],style:TextStyle(fontWeight:FontWeight.bold)),subtitle:Text("Plot ${t['plot']} Bal ₦${t['bal']}"),trailing:Icon(Icons.arrow_forward_ios,size:14),onTap:()=>_det(tens.indexOf(t))))).toList()
    ]));}
    else if(i==1){ b=Column(children:[Padding(padding:EdgeInsets.all(12),child:Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text("Properties / Tenants (${tens.length})",style:TextStyle(fontWeight:FontWeight.bold,fontSize:16)),ElevatedButton(onPressed:_addT,child:Text("+ Add"))])), Expanded(child:tens.isEmpty?Center(child:Text("No tenant. Add with Purchase, Security, Dev, Estate Due")):ListView.builder(itemCount:tens.length,itemBuilder:(_,k){var t=tens[k];return Card(margin:EdgeInsets.symmetric(horizontal:10,vertical:5),child:ListTile(title:Text(t['name'],style:TextStyle(fontWeight:FontWeight.bold)),subtitle:Text("Plot:${t['plot']} | P:₦${t['pur']} S:₦${t['sec']} D:₦${t['dev']} E:₦${t['due']}\nTot ₦${t['tot']} Paid ₦${t['paid']} Bal ₦${t['bal']}"),isThreeLine:true,onTap:()=>_det(k),trailing:Icon(Icons.more_vert)));}))]);}
    else{ var pc=TextEditingController(); var ec=TextEditingController(text:en); b=SingleChildScrollView(padding:EdgeInsets.all(16),child:Column(children:[Icon(Icons.person_pin,size:70,color:Color(0xFF2E7D32)),Text(en,style:TextStyle(fontWeight:FontWeight.bold,fontSize:18)),SizedBox(height:20), TextField(controller:ec,decoration:InputDecoration(labelText:"Editable Estate Name",border:OutlineInputBorder(),prefixIcon:Icon(Icons.edit))),SizedBox(height:10),SizedBox(width:double.infinity,child:ElevatedButton(onPressed:(){setState(()=>en=ec.text); _save(); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text("Updated")));},child:Text("Update Name"))),Divider(height:30),TextField(controller:pc,decoration:InputDecoration(labelText:"Changeable Password - New",border:OutlineInputBorder(),prefixIcon:Icon(Icons.lock))),SizedBox(height:10),SizedBox(width:double.infinity,child:ElevatedButton(style:ElevatedButton.styleFrom(backgroundColor:Color(0xFF2E7D32)),onPressed:()async{var p=await SharedPreferences.getInstance(); await p.setString('app_password',pc.text); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text("Password changed to ${pc.text}")));},child:Text("Change Password",style:TextStyle(color:Colors.white)))),SizedBox(height:25),OutlinedButton.icon(icon:Icon(Icons.logout),label:Text("Logout"),onPressed:()=>Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>LoginScreen()))) ]));}
    return Scaffold(appBar:AppBar(title:Text("Estate Management"),backgroundColor:Color(0xFF2E7D32),foregroundColor:Colors.white),body:b,bottomNavigationBar:BottomNavigationBar(currentIndex:i,selectedItemColor:Color(0xFF2E7D32),onTap:(x)=>setState(()=>i=x),items:[BottomNavigationBarItem(icon:Icon(Icons.dashboard),label:"Dashboard"),BottomNavigationBarItem(icon:Icon(Icons.home_work),label:"Properties"),BottomNavigationBarItem(icon:Icon(Icons.person),label:"Profile")]),floatingActionButton:i==0?FloatingActionButton(backgroundColor:Color(0xFF2E7D32),onPressed:_addP,child:Icon(Icons.add,color:Colors.white)):FloatingActionButton(backgroundColor:Color(0xFF2E7D32),onPressed:_addT,child:Icon(Icons.person_add,color:Colors.white)));
